   const auto primary=checkpoint(runtime.at("restart")),independent=checkpoint(item.at("expectedWitnessCommitment"));require(primary.digest!=independent.digest,"primary/witness token roles merged");const Json empty{{"attestation",nullptr},{"format","nano-beacon-signing-v1"},{"genesisValidatorsRoot",manifest.at("genesisValidatorsRoot")},{"proposal",nullptr},{"publicKey",hex(public_key)},{"slotsPerEpoch","0x8"}};auto snapshot=empty;if(index==proposer)snapshot["proposal"]={{"root",proposal_root},{"slot","0x1"}};
