   stage="read-only-namespace-metadata";metadata_kind(primary_path,Json{{"chainId",quantity(chain)},{"genesisHash",hex(execution)},{"consensus","nano-beacon-signing-v1"}});metadata_kind(witness_path,Json{{"chainId",quantity(chain)},{"genesisHash",hex(execution)},{"consensus","nano-beacon-signing-witness-v1"}});
